values: dict[str, Any] = {}
for f in fields(cls):
    if not f.init:
        continue
    env_val = os.environ.get(f.name.upper())
    if env_val is not None:
        # parse env_val based on type if needed
        v = env_val
    else:
        v = configurable.get(f.name)
    if v is not None:
        values[f.name] = v
return cls(**values)
